import pickle
import numpy as np
import pandas as pd
import streamlit as st
from sklearn.base import BaseEstimator, TransformerMixin

# ══════════════════════════════════════════════════════════════════════════
# LogColumnScaler — MUST match the class used in 1_GPR_pkl.py
# ══════════════════════════════════════════════════════════════════════════
_EPS = 1e-300


class LogColumnScaler(BaseEstimator, TransformerMixin):
    def __init__(self, columns, log_columns=None):
        self.columns = columns
        self.log_columns = log_columns

    def fit(self, X, y=None):
        X = np.asarray(X, dtype=float)
        columns = list(self.columns)
        log_columns = list(self.log_columns) if self.log_columns is not None else []
        self.log_mask_ = np.array([c in log_columns for c in columns])

        Xt = self._forward_log(X)
        self.mean_ = Xt.mean(axis=0)
        self.std_ = Xt.std(axis=0)
        self.std_[self.std_ == 0] = 1.0
        return self

    def _forward_log(self, X):
        Xt = X.copy()
        if self.log_mask_.any():
            Xt[:, self.log_mask_] = np.log10(np.maximum(X[:, self.log_mask_], _EPS))
        return Xt

    def transform(self, X):
        X = np.asarray(X, dtype=float)
        return (self._forward_log(X) - self.mean_) / self.std_

    def inverse_transform(self, X):
        X = np.asarray(X, dtype=float)
        Xt = X * self.std_ + self.mean_
        Xo = Xt.copy()
        if self.log_mask_.any():
            Xo[:, self.log_mask_] = np.power(10.0, Xt[:, self.log_mask_])
        return Xo


