# Confidence tiers from leverage / h*:
#   ratio <= 1.0                -> High   (inside the training domain)
#   1.0 < ratio <= MEDIUM_LIMIT -> Medium (moderately outside)
#   ratio > MEDIUM_LIMIT        -> Low    (well outside / extrapolating)
MEDIUM_RATIO_LIMIT = 2.0
Z_95 = 1.96                       # 95 % predictive interval


def pretty_label(col_name):
    return LABEL_MAP.get(col_name, col_name)


INPUT_LABEL_OVERRIDES = {
    'E': 'E\u0303',               # Ẽ (normalized potential)
    'd': 'd\u0303',               # d̃ (normalized diameter)
}


def input_label(feat):
    return INPUT_LABEL_OVERRIDES.get(feat, feat)


# ══════════════════════════════════════════════════════════════════════════
# Bundle loading
# ══════════════════════════════════════════════════════════════════════════
@st.cache_resource(show_spinner="Loading model…")
def load_bundle(path):
    with open(path, 'rb') as f:
        return pickle.load(f)


# ══════════════════════════════════════════════════════════════════════════
# GPR prediction with uncertainty
#   The GPR works in normalized (log10 + z-score) target space. Its predictive
#   std is converted to a 95 % interval in that space and mapped back through
#   the target scaler, so log-scaled outputs get correct (asymmetric) bounds.
# ══════════════════════════════════════════════════════════════════════════
def predict_with_uncertainty(model, row_df, input_cols):
    xs = model.named_steps['xscaler']
    reg = model.named_steps['reg']
    gpr = reg.regressor_
    yscaler = reg.transformer_

    Xs = xs.transform(row_df[input_cols].values)
    mean_n, std_n = gpr.predict(Xs, return_std=True)
    mean_n = np.atleast_2d(mean_n)
    std_n = np.asarray(std_n).reshape(mean_n.shape)

    mean = yscaler.inverse_transform(mean_n)[0]
    lo = yscaler.inverse_transform(mean_n - Z_95 * std_n)[0]
    hi = yscaler.inverse_transform(mean_n + Z_95 * std_n)[0]
    return mean, np.minimum(lo, hi), np.maximum(lo, hi), std_n[0]


# ══════════════════════════════════════════════════════════════════════════
# Applicability-domain (Williams-plot-style leverage) helpers
# ══════════════════════════════════════════════════════════════════════════
def add_intercept(A):
    return np.hstack([np.ones((A.shape[0], 1)), A])


def compute_new_point_leverage(new_row_df, xscaler, input_cols, ad):
    x_scaled = xscaler.transform(new_row_df[input_cols].values)
    x_design = add_intercept(x_scaled)
    return float((x_design @ ad['XtX_inv'] @ x_design.T)[0, 0])


def confidence_tier(h, h_star):
    ratio = h / h_star if h_star > 0 else float('inf')
    if ratio <= 1.0:
        return "High", ratio
    elif ratio <= MEDIUM_RATIO_LIMIT:
        return "Medium", ratio
    return "Low", ratio


def out_of_range_inputs(new_inputs, ranges):
    return [c for c, val in new_inputs.items()
            if not (ranges[c][0] <= val <= ranges[c][1])]


