# Main — inputs
# ══════════════════════════════════════════════════════════════════════════
st.title("🫧 Hydrogen Bubble Dynamics Predictor")
st.caption("A Gaussian Process Regression surrogate for a single hydrogen bubble "
           "detaching from an electrode, with 95 % predictive intervals and an "
           "applicability-domain reliability check.")

st.markdown("### Inputs")
input_vals = {}
cols = st.columns(len(input_cols))

for col_obj, feat in zip(cols, input_cols):
    lo, hi = ad['ranges'][feat]
    default = (lo + hi) / 2
    fmt = "%.6e" if (hi / lo if lo > 0 else 0) > 1000 else "%.4f"
    with col_obj:
        val = st.number_input(
            input_label(feat), value=float(default), format=fmt, key=f'inp_{feat}',
            help=f"Training range: {lo:.4g} to {hi:.4g}",
        )
        input_vals[feat] = val

predict_clicked = st.button("⚡ Predict", use_container_width=True)

# ══════════════════════════════════════════════════════════════════════════
# Predict + reliability
# ══════════════════════════════════════════════════════════════════════════
if predict_clicked:
    row = pd.DataFrame([input_vals])[input_cols]

    preds, lo95, hi95, std_n = predict_with_uncertainty(model, row, input_cols)
    h = compute_new_point_leverage(row, xscaler, input_cols, ad)
    tier, ratio = confidence_tier(h, ad['h_star'])
    oor = out_of_range_inputs(input_vals, ad['ranges'])

    pred_by_name = dict(zip(target_cols, preds))
    lo_by_name = dict(zip(target_cols, lo95))
    hi_by_name = dict(zip(target_cols, hi95))

